        // if there are more default values than specified, add them to
        // the list.
        List defaults = (List) this.defaultValues.get(option);
        if (defaults != null && defaults.size() > valueList.size()) {
            // copy the list first
            valueList = new ArrayList(valueList);
            valueList.addAll(defaults.subList(valueList.size(), defaults.size()));
