      Collection<Definition> lhs = getCallableDefinitions(definitionProvider,
          name.getFirstChild());
      Collection<Definition> rhs = getCallableDefinitions(definitionProvider,
          name.getLastChild());
      if (lhs == null || rhs == null) {
        return null;
      }
      result.addAll(lhs);
      result.addAll(rhs);
      return result;
    } else if (name.getType() == Token.HOOK) {
      Collection<Definition> trueExpr = getCallableDefinitions(definitionProvider,
          name.getFirstChild().getNext());
      Collection<Definition> falseExpr = getCallableDefinitions(definitionProvider,
          name.getLastChild());
      if (trueExpr == null || falseExpr == null) {
        return null;
      }
      result.addAll(trueExpr);
      result.addAll(falseExpr);
      return result;
    } else {
      return null;
    }
