                return absYA < absYB ? xA : xB;
            case LEFT_SIDE :
                return xA;
            case RIGHT_SIDE :
                return xB;
            case BELOW_SIDE :
                return (yA <= 0) ? xA : xB;
            case ABOVE_SIDE :
                return (yA <  0) ? xB : xA;
            default :
                // this should never happen
                throw new MathInternalError(null);
            }
        }

